function link(href,label,sub,icon){const a=node('a',page==='profile'?'':label);a.href=href;a.addEventListener('click',e=>{if(!E.confirmLeave(false))e.preventDefault();});if(page==='profile'){const symbol=node('span',icon);symbol.className='np-entry-icon';symbol.setAttribute('aria-hidden','true');const text=node('span','');text.className='np-entry-text';text.append(node('strong',label),node('small',sub));const arrow=node('span','›');arrow.className='np-chevron';arrow.setAttribute('aria-hidden','true');a.append(symbol,text,arrow);}return a;}
